let toasts = $state({
    "top-left": [],
    "top-center": [],
    "top-right": [],
    "bottom-left": [],
    "bottom-center": [],
    "bottom-right": [],
});
/**
 * Add a toast to the screen.
 * @example
 * // Simple notification
 * addToast({
 *     title: 'Success',
 *     content: 'File saved',
 *     position: 'bottom-right',
 *     autoClose: 5000,
 * });
 *
 * // Custom component
 * addToast({
 *     component: MyCustomToast,
 *     props: { data: myData },
 *     position: 'top-center',
 * });
 *
 * // Custom render function
 * addToast({
 *     render: (close) => myRenderFn(close),
 *     position: 'bottom-left',
 * });
 */
export function addToast(opts) {
    const id = crypto.randomUUID();
    const position = opts.position || "bottom-right";
    const item = {
        id,
        position,
        ...opts,
    };
    toasts[position].push(item);
    const close = () => removeToast(id);
    if (opts.autoClose) {
        setTimeout(close, opts.autoClose);
    }
    return { id, close };
}
/**
 * Remove a toast by ID.
 */
export function removeToast(id) {
    for (const position of Object.keys(toasts)) {
        toasts[position] = toasts[position].filter(t => t.id !== id);
    }
}
/**
 * Clear all toasts, optionally filtered by position.
 */
export function clearToasts(position) {
    if (position) {
        toasts[position] = [];
    }
    else {
        for (const pos of Object.keys(toasts)) {
            toasts[pos] = [];
        }
    }
}
export { toasts };
